const input = $json;

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

if (!input.lead_id || !uuidRegex.test(input.lead_id)) {
  throw new Error(`Invalid or missing lead_id: ${input.lead_id || "empty"}`);
}

const resolvedBy = input.resolved_by || "human_operator";
const resolutionNote =
  input.resolution_note ||
  "Caso resuelto manualmente. Bot reactivado.";

const resumeStage = input.resume_stage || "closing";
const nextGoal = input.next_goal || "continue_conversation";

return [{
  lead_id: input.lead_id,
  resolved_by: resolvedBy,
  resolution_note: resolutionNote,
  resume_stage: resumeStage,
  next_goal: nextGoal,
  reactivated_at: new Date().toISOString()
}];

const originalInput = $("validate_reactivation_input").first().json;
const handoffResult = $("DB_Close_Open_Handoff_Cases").first().json || {};
const stateResult = $("DB_Reactivate_Lead_State").first().json || {};

const closedCaseId = handoffResult?.id || null;

return [{
  flow_name: "reactivate_bot_after_handoff",
  lead_id: originalInput.lead_id,
  channel: "internal",
  stage_before: "human_handoff",
  latest_user_message: null,
  allowed_actions: [],
  decision: {
    action: "reactivate_bot",
    reason: "Human handoff resolved manually"
  },
  meta: {
    resolved_by: originalInput.resolved_by,
    resolution_note: originalInput.resolution_note,
    closed_handoff_case_id: closedCaseId,
    handoff_case_closed: !!closedCaseId,
    new_state: {
      stage: stateResult.stage || originalInput.resume_stage,
      human_handoff: stateResult.human_handoff ?? false,
      next_goal: stateResult.next_goal || originalInput.next_goal,
      last_bot_action: stateResult.last_bot_action || "bot_reactivated_after_handoff"
    }
  },
  llm: null,
  idempotency_key: `${originalInput.lead_id}__reactivate_bot__${Date.now()}`,
  created_at: new Date().toISOString()
}];

const input = $("validate_reactivation_input").first().json;
const closedCase = $("DB_Close_Open_Handoff_Cases").first().json || {};
const state = $("DB_Reactivate_Lead_State").first().json || {};
const audit = $json || {};

return [{
  success: true,
  action: "reactivate_bot_after_handoff",
  lead_id: input.lead_id,
  bot_reactivated: state?.human_handoff === false,
  handoff_case_closed: !!closedCase?.id,
  closed_handoff_case_id: closedCase?.id || null,
  new_state: {
    stage: state?.stage || input.resume_stage,
    human_handoff: state?.human_handoff ?? false,
    next_goal: state?.next_goal || input.next_goal,
    last_bot_action: state?.last_bot_action || "bot_reactivated_after_handoff"
  },
  audit_log_id: audit?.id || null,
  notes: [
    closedCase?.id ? "handoff_case_resolved" : "no_open_handoff_case_found",
    state?.lead_id ? "lead_state_reactivated" : "lead_state_not_found",
    state?.human_handoff === false ? "bot_can_reply_again" : "bot_reactivation_not_confirmed"
  ]
}];
